   `reorderForAnthropic` algorithm (pseudo‑code):
   ```ts
   function reorderForAnthropic(messages: CoreMessage[]): CoreMessage[] {
     const result: CoreMessage[] = [];
     const toolBlocks: CoreMessage[] = [];
     let finalAssistantIndex = -1;

     for (let i = 0; i < messages.length; i++) {
       const msg = messages[i];
       if (msg.role === 'assistant' && Array.isArray(msg.content) && msg.content.some(c => c.type === 'tool-call')) {
         // collect tool‑call block and its following tool‑result block (which must be next)
         toolBlocks.push(msg);
         if (i + 1 < messages.length && messages[i + 1].role === 'tool') {
           toolBlocks.push(messages[i + 1]);
           i++; // skip tool result (already consumed)
         }
       } else if (msg.role === 'assistant' && typeof msg.content === 'string') {
         // this is a plain assistant response; keep track of the *last* one
         finalAssistantIndex = result.length;
         result.push(msg);
       } else {
         result.push(msg);
